SELECT /* SQL_ID: ci.sc.cm.am.ApiMngMapper.select.selectStndApiList (표준API목록조회) */ API_VER_SN /* API버전일련번호 */ ,API_ID /* API아이디 */ ,API_NM /* API명 */ ,SAAS_PRDCT_TYPE_CD /* SAAS제공유형코드 */ ,USCM.SF_COMM_CD_NM(SAAS_PRDCT_TYPE_CD) AS SAAS_PRDCT_TYPE_NM /* SAAS제공유형코드명 */ ,API_DMND_RSPNS_SE_CD /* API요청응답구분코드 */ ,USCM.SF_COMM_CD_NM(API_DMND_RSPNS_SE_CD) AS API_DMND_RSPNS_SE_NM /* API요청응답구분코드명 */ ,HTTP_CMNC_SE_CD /* HTTP통신구분코드 */ ,USCM.SF_COMM_CD_NM(HTTP_CMNC_SE_CD) AS HTTP_CMNC_SE_NM /* HTTP통신구분코드명 */ ,URI_ADDR /* URI주소 */ ,FRST_CRT_PRCR_ID /* 최초생성처리자아이디 */ ,FRST_CRT_DT /* 최초생성일시 */ ,LAST_CHG_PRCR_ID /* 최종변경처리자아이디 */ ,LAST_CHG_DT /* 최종변경일시 */ ,CASE WHEN EXISTS ( SELECT 1 FROM USCM.TBCM_PRDCT_API_CMNCRSLT_L R LEFT JOIN USCM.TBCM_SAAS_PRDCT_M G ON G.SAAS_PRDCT_ID = R.SAAS_PRDCT_ID WHERE R.API_ID = S.API_ID AND R.API_VER_SN = S.API_VER_SN AND G.SAAS_PRDCT_API_VER_SN = S.API_VER_SN AND G.GDS_GDNTC_REG_YN = 'Y' /* AND R.CMNC_RSLT_CD = 'A0050002' */ AND R.SRVR_SE_CD = 'A0060002' )THEN 'Y' ELSE 'N' END AS GDS_GDNTC_REG_YN , CASE WHEN S.API_VER_SN < ( SELECT MAX(API_VER_SN) FROM USCM.TBCM_STD_API_M )THEN 'N' ELSE 'Y' END AS LAST_VER_EDIT_YN /* 최신버전수정가능여부 */ FROM USCM.TBCM_STD_API_M S WHERE 1 = 1 AND S.USE_YN = 'Y'
AND API_NM ILIKE '%' || #{apiNm} || '%'
AND SAAS_PRDCT_TYPE_CD = #{saasPrdctTypeCd}
AND HTTP_CMNC_SE_CD = #{httpCmncSeCd}
AND API_VER_SN = #{apiVerSn}
AND API_DMND_RSPNS_SE_CD = #{apiDmndRspnsSeCd}
ORDER BY API_VER_SN DESC, FRST_CRT_DT DESC, API_NM ASC LIMIT #{pageSize} OFFSET #{offset}

SELECT /* SQL_ID: ci.sc.cm.am.ApiMngMapper.select.selectStndApiCnt (표준API목록건수조회) */
	COUNT(*)
FROM USCM.TBCM_STD_API_M S
WHERE 1 = 1
AND S.USE_YN = 'Y'

	AND API_NM ILIKE '%' || #{apiNm} || '%'


	AND SAAS_PRDCT_TYPE_CD = #{saasPrdctTypeCd}


	AND HTTP_CMNC_SE_CD = #{httpCmncSeCd}


	AND API_VER_SN = #{apiVerSn}


	AND API_DMND_RSPNS_SE_CD = #{apiDmndRspnsSeCd}

mapper.insert:
INSERT /* SQL_ID: ci.sc.cm.am.ApiMngMapper.insert.insertStndApi (표준API등록_API기본정보) */
INTO USCM.TBCM_STD_API_M (
								API_VER_SN 				/* API버전일련번호 		*/
								,API_ID 				/* API아이디 			*/
								,API_NM 				/* API명 			*/
								,SAAS_PRDCT_TYPE_CD 	/* SAAS공형태코드 		*/
								,API_DMND_RSPNS_SE_CD 	/* API요청응답구분코드 	*/
								,HTTP_CMNC_SE_CD		/* HTTP통신구분코드 	*/
								,URI_ADDR 				/* URI주소 			*/
								,FRST_CRT_PRCR_ID		/* 최초생성처리자아이디 	*/
								,FRST_CRT_DT			/* 최초생성일시 		*/
								,LAST_CHG_PRCR_ID		/* 최종변경처리자아이디 	*/
								,LAST_CHG_DT			/* 최종변경일시 		*/
								,USE_YN 
							) 
					 VALUES (
								#{apiVerSn}
								,#{apiId}
								,#{apiNm}
								,#{saasPrdctTypeCd}
								,#{apiDmndRspnsSeCd}
								,#{httpCmncSeCd}
								,#{uriAddr}
								,#{frstCrtPrcrId}
								,TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS') 
								,#{lastChgPrcrId}
								,TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS') 
								,'Y'
							)

INSERT INTO /* SQL_ID: ci.sc.cm.am.ApiMngMapper.insert.insertStndApiArtcl (표준API등록_API항목정보) */
USCM.TBCM_STD_API_ARTCL_L (
								API_VER_SN				/* API버전일련번호 		*/
								,API_ID					/* API아이디 			*/
								,API_ARTCL_SE_CD		/* API항목구분코드 		*/
								,API_ARTCL_SN			/* API항목일련번호 		*/
								,API_ARTCL_ATRB_NM		/* API항목속성명 		*/
								,API_ARTCL_DATA_TYPE_CD	/* API항목유형코드 		*/
								,API_ARTCL_ESNTL_YN		/* API항목필수여부 		*/
								,API_ARTCL_CN			/* API항목내용 		*/
								,FRST_CRT_PRCR_ID		/* 최초생성처리자아이디 	*/
								,FRST_CRT_DT			/* 최초생성일시 		*/
								,LAST_CHG_PRCR_ID		/* 최종변경처리자아이디 	*/
								,LAST_CHG_DT			/* 최종변경일시 		*/
							) 
					 VALUES (
								#{apiVerSn}
								,#{apiId}
								,#{apiArtclSeCd}
								,#{apiArtclSn}
								,#{apiArtclAtrbNm}
								,#{apiArtclDataTypeCd}
								,#{apiArtclEsntlYn}
								,#{apiArtclCn}
								,#{frstCrtPrcrId}
								,TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
								,#{lastChgPrcrId}
								,TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
							)

