		UPDATE /* SQL_ID: ci.sc.cm.am.ApiMngMapper.delete.deleteStndApi (표준API삭제_API정보) */
		USCM.TBCM_STD_API_M
		SET
			USE_YN = 'N'
         	,LAST_CHG_PRCR_ID = #{lastChgPrcrId}
         	,LAST_CHG_DT = TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS') 
		WHERE API_VER_SN = #{apiVerSn} 
		AND API_ID = #{apiId};

