DELETE /* SQL_ID: ci.sc.cm.am.ApiMngMapper.delete.deleteStndApiArtcl (표준API삭제_API항목정보) */
FROM USCM.TBCM_STD_API_ARTCL_L
WHERE API_VER_SN = #{apiVerSn} 
AND API_ID = #{apiId};

