INSERT /* SQL_ID: ci.sc.cm.am.ApiMngMapper.insert.insertStndApiVer (표준API_버전추가) */ 
INTO USCM.TBCM_API_VER_B (
								API_VER_SN			/* API버전일련번호 		*/
								,API_VER_CHG_RSN	/* API버전변경사유 		*/
								,USE_YN				/* 사용여부 			*/
								,FRST_CRT_DT		/* 최초생성일자 		*/
								,FRST_CRT_PRCR_ID	/* 최초생성처리자아이디	*/
					 			,LAST_CHG_DT		/* 최종변경일자			*/
					 			,LAST_CHG_PRCR_ID	/* 최종변경처리자아이디	*/
					 		) 
					 VALUES (
								#{apiVerSn}
								,#{apiVerChgRsn}
								,#{useYn}
								,TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
								,#{frstCrtPrcrId}
								,TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
								,#{lastChgPrcrId}
							)

mapper.select:
		SELECT /* SQL_ID: ci.sc.cm.am.ApiMngMapper.select.selectProdList (상품-표준API관계, 통신내역 테이블 등록 위한 상품정보 조회) */
		       G.SAAS_PRDCT_ID 			/* SAAS제품아이디	*/
		     , G.SAAS_PRDCT_TYPE_CD		/* SAAS제품유형코드	*/
		FROM   USCM.TBCM_SAAS_PRDCT_M G
		WHERE  G.USE_YN = 'Y'
		AND (
         	 G.SAAS_PRDCT_API_VER_SN < #{apiVerSn}
         	 OR (G.SAAS_PRDCT_API_VER_SN = #{apiVerSn} AND G.GDS_GDNTC_REG_YN = 'N')
    		)

			AND G.SAAS_PRDCT_TYPE_CD = #{saasPrdctTypeCd}

mapper.insert:
INSERT /* SQL_ID: ci.sc.cm.am.ApiMngMapper.insert.insertProdStndApiR  (상품표준API관계 등록) */
INTO USCM.TBCM_SAAS_PRDCT_API_R (
	SAAS_PRDCT_ID
	, API_VER_SN
	, API_ID
)
VALUES (
	  #{saasPrdctId}
	, #{apiVerSn}
	, #{apiId}
)

INSERT /* SQL_ID: ci.sc.cm.am.ApiMngMapper.insert.insertProdApiTest (상품API통신항목 등록) */
INTO USCM.TBCM_PRDCT_API_CMNCRSLT_L (
	SAAS_PRDCT_ID		/* SAAS제품아이디	*/
	, SRVR_SE_CD		/* 서버구분코드		*/
	, API_ID			/* API아이디		*/
	, API_VER_SN		/* API버전일련번호	*/
	, CMNC_RSLT_CD		/* 통신결과코드		*/
	, FRST_CRT_PRCR_ID	/* 최초생성처리자아이디*/
	, FRST_CRT_DT		/* 최초생성일시		*/
	, LAST_CHG_PRCR_ID	/* 최종변경처리자아이디*/
	, LAST_CHG_DT		/* 최종변경일시		*/
)
VALUES (
	  #{saasPrdctId}
	, #{srvrSeCd}
	, #{apiId}
	, #{apiVerSn}  
	, #{cmncRsltCd}
	, #{frstCrtPrcrId}
	, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
	, #{lastChgPrcrId}
	, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
)

mapper.update:
  	UPDATE  /* SQL_ID: ci.sc.cm.pm.ApiMngMapper.select.updateProdApiTest (상품API통신항목수정_통신결과코드) */ 
  		USCM.TBCM_PRDCT_API_CMNCRSLT_L R
    SET 
    	CMNC_RSLT_CD = #{cmncRsltCd}                  
        , CMNC_DT = NULL 
        , CMNC_RSLT_CN = NULL  
        , LAST_CHG_PRCR_ID = #{lastChgPrcrId}
        , LAST_CHG_DT = TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
   	FROM USCM.TBCM_SAAS_PRDCT_M G
   	WHERE R.API_ID = #{apiId}
	    AND R.API_VER_SN = #{apiVerSn}
	    AND R.SRVR_SE_CD  = #{srvrSeCd}
	    AND R.CMNC_RSLT_CD != #{cmncRsltCd}
	    AND G.SAAS_PRDCT_ID = R.SAAS_PRDCT_ID     
	    AND G.SAAS_PRDCT_API_VER_SN = R.API_VER_SN

mapper.delete:
DELETE /* SQL_ID: ci.sc.cm.am.ApiMngMapper.delete.deleteProdStndApiR (상품표준API관계삭제) */
FROM USCM.TBCM_SAAS_PRDCT_API_R 
WHERE API_ID = #{apiId}
AND API_VER_SN = #{apiVerSn}

		DELETE /* SQL_ID: ci.sc.cm.am.ApiMngMapper.delete.deleteProdApiTest (상품API통신항목삭제) */
		FROM USCM.TBCM_PRDCT_API_CMNCRSLT_L R
		WHERE R.API_ID = #{apiId}
		AND R.API_VER_SN = #{apiVerSn}

    		AND EXISTS (
      					 SELECT 1
      					 FROM USCM.TBCM_SAAS_PRDCT_M G
      					 WHERE G.SAAS_PRDCT_ID = R.SAAS_PRDCT_ID
        				 AND G.GDS_GDNTC_REG_YN = #{gdsGdntcRegYn}
    					)

mapper.update:
  	UPDATE  /* SQL_ID: ci.sc.cm.pm.ApiMngMapper.insert.updateCertKeyToN (0923 상품인증관리내역수정) */
  		USCM.TBCM_CMNC_MNG_L M  
  	SET 
  		API_CMNC_SCS_YN  = 'N'
       , LAST_CHG_PRCR_ID = #{lastChgPrcrId}
       , LAST_CHG_DT      = TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
   	WHERE M.SAAS_PRDCT_ID = #{saasPrdctId}
    AND M.SRVR_SE_CD    = #{srvrSeCd}
    AND M.API_CMNC_SCS_YN = 'Y'  

       AND EXISTS (
			         SELECT 1
			         FROM USCM.TBCM_PRDCT_API_CMNCRSLT_L R
			         JOIN USCM.TBCM_SAAS_PRDCT_M G
			         	ON G.SAAS_PRDCT_ID = R.SAAS_PRDCT_ID
			         WHERE R.SAAS_PRDCT_ID = M.SAAS_PRDCT_ID
			            AND R.SRVR_SE_CD    = M.SRVR_SE_CD
			            AND R.API_ID        = #{apiId}
			            AND R.API_VER_SN    = #{apiVerSn}
			            AND G.USE_YN        = 'Y'
			            AND G.GDS_GDNTC_REG_YN = 'N'
			            AND G.SAAS_PRDCT_API_VER_SN = #{apiVerSn}  
			       )
